import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Path;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class GoodFileServlet extends HttpServlet {
    // Change this to a trusted directory for downloadable files.
    private static final String DOWNLOAD_ROOT = "/var/app/downloads";

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userFilename = request.getParameter("file");

        if (userFilename == null || userFilename.trim().isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        // Reject path separators and parent-directory references.
        if (userFilename.contains("..") || userFilename.contains("/") || userFilename.contains("\\")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        // Use canonical paths to prevent path-resolution escapes.
        Path baseDir = new File(DOWNLOAD_ROOT).getCanonicalFile().toPath();
        Path requestedPath = new File(DOWNLOAD_ROOT, userFilename).getCanonicalFile().toPath();

        // Ensure the resolved file remains inside the base directory.
        if (!requestedPath.startsWith(baseDir)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        File file = requestedPath.toFile();

        if (!file.exists() || !file.isFile()) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        try (FileInputStream in = new FileInputStream(file)) {
            response.setContentType("application/octet-stream");
            in.transferTo(response.getOutputStream());
        }
    }
}

