import javax.servlet.ServletException;
import javax.servlet.http.*;
import java.io.*;
import java.nio.file.*;

// Fixed: resolve user input inside an allowed base directory before using the Java File API.
public class FileServlet extends HttpServlet {
    private static final Path BASE_DIR = Paths.get("/var/app/data").toAbsolutePath().normalize();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String fileName = req.getParameter("file");

        if (fileName == null || fileName.isEmpty()) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        Path requested = BASE_DIR.resolve(fileName).normalize();
        if (!requested.startsWith(BASE_DIR)) {
            resp.sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        File f = requested.toFile();
        if (f.exists() && f.isFile()) {
            try (BufferedReader reader = new BufferedReader(new FileReader(f))) {
                resp.setContentType("text/plain");
                reader.lines().forEach(resp.getWriter()::println);
            }
        } else {
            resp.sendError(HttpServletResponse.SC_NOT_FOUND);
        }
    }
}

