{
  "rubric_title": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "description": "A comprehensive framework for evaluating software engineering performance across technical, collaborative, and professional dimensions.",
  "categories": [
    {
      "name": "Technical Proficiency & Code Quality",
      "weight": 40,
      "criteria": [
        {
          "id": "T1",
          "title": "Code Quality & Maintainability",
          "description": "Assesses the cleanliness, readability, and modularity of code. Includes adherence to coding standards and best practices.",
          "levels": {
            "Exceeds Expectations (5)": "Code is exceptionally clean, well-documented, and serves as a model for the team. Proactively refactors legacy code and introduces design patterns where appropriate without over-engineering.",
            "Meets Expectations (4)": "Consistently produces clean, readable, and maintainable code that adheres to established guidelines. Requires minimal review effort.",
            "Developing (3)": "Code is functional but occasionally lacks clarity or consistency. May require significant refactoring during code reviews.",
            "Needs Improvement (2)": "Frequently submits code with poor structure, lack of documentation, or violations of core style guides. Requires extensive rework."
          }
        },
        {
          "id": "T2",
          "title": "Problem Solving & Technical Depth",
          "description": "Evaluates the ability to analyze complex problems, select appropriate technologies, and implement efficient solutions.",
          "levels": {
            "Exceeds Expectations (5)": "Demonstrates deep expertise in the tech stack. Solves ambiguous or novel problems with innovative approaches. Mentors others on complex technical challenges.",
            "Meets Expectations (4): "Solidly solves standard and moderately complex problems using correct algorithms and data structures. Understands trade-offs between different solutions.",
            "Developing (3)": "Can solve routine tasks but struggles with complex architectural decisions or optimization. Relies heavily on guidance for non-standard issues.",
            "Needs Improvement (2)": "Struggles to implement basic features correctly. Frequently makes logical errors or chooses inefficient solutions without understanding why."
          }
        },
        {
          "id": "T3",
          "title": "Testing & Quality Assurance",
          "description": "Assesses the rigor of unit, integration, and end-to-end testing practices.",
          "levels": {
            "Exceeds Expectations (5)": "Writes comprehensive test suites that cover edge cases and failure modes. Improves existing test infrastructure and promotes TDD/BDD practices within the team.",
            "Meets Expectations (4)": "Consistently writes effective unit tests for new features. Ensures high coverage for critical paths and fixes bugs promptly when tests fail.",
            "Developing (3)": "Writes basic tests but often misses edge cases. Test coverage is inconsistent and may be superficial.",
            "Needs Improvement (2)": "Rarely writes tests or writes tests that are brittle and do not effectively verify logic. Relies solely on manual QA."
          }
        }
      ]
    },
    {
      "name": "Collaboration & Communication",
      "weight": 30,
      "criteria": [
        {
          "id": "C1",
          "title": "Team Collaboration",
          "description": "Evaluates how effectively the engineer works with peers, product managers, and other stakeholders.",
          "levels": {
            "Exceeds Expectations (5)": "Actively fosters a positive team culture. Shares knowledge generously, mentors junior engineers, and facilitates smooth cross-functional collaboration.",
            "Meets Expectations (4)": "Works well within the team. Participates in stand-ups and planning sessions constructively. Responds to requests from teammates in a timely manner.",
            "Developing (3)": "Cooperates when asked but is passive in team activities. Occasionally misses communication updates or deadlines affecting team flow.",
            "Needs Improvement (2)": "Isolates work or creates friction with teammates. Fails to communicate blockers or progress, leading to project delays."
          }
        },
