{
  "startup_pitch": {
    "name": "Tipperary",
    "tagline": "The social proof layer for tipping.",
    "one_line_pitch": "Tipperary is an app that tells people the average tip size for each restaurant, so diners can tip confidently and fairly while restaurants understand expected tipping behavior.",
