        "Crowdsourced anonymous tip submissions with confidence scores based on data volume and recency.",
        "Optional receipt upload or manual check entry to improve data accuracy without requiring private payment details.",
        "Local and neighborhood benchmarks that show whether a restaurant average tip is above or below the surrounding area.",
        "Restaurant dashboard for managers to see tipping trends, average check size, and service feedback."
      ],
      "user_flow": [
        "User searches for a restaurant or scans a QR code at the table.",
        "Tipperary displays the average tip percentage and typical tip range.",
        "During checkout, the user enters the check amount and receives a recommended tip.",
        "After payment, the user can optionally confirm the tip or submit a receipt for improved accuracy.",
        "Tipperary updates the restaurant profile with anonymized, weighted data."
      ]
    },
    "product_design": {
      "consumer_app": {
        "platforms": [
          "iOS",
          "Android",
          "web",
          "in-restaurant QR code"
        ],
        "key_screens": [
          "search",
          "restaurant tip profile",
          "tip calculator",
          "local trends",
          "receipt submission",
          "profile and privacy settings"
        ]
      },
      "data_engine": {
        "inputs": [
          "anonymous user tip entries",
          "optional receipt images",
          "public menu and price data",
          "restaurant metadata",
          "local dining benchmarks"
        ],
        "normalization": [
          "Adjust for check size and menu price.",
          "Adjust for party size and service type.",
          "Weight recent data higher.",
          "Filter outliers using median-based models.",
          "Display confidence ranges instead of fake precision."
        ],
        "privacy": "All submissions are anonymized, and no payment account data is required for core use."
      },
      "monetized_features": [
        "Restaurant Pro dashboard",
        "API access for payment processors and restaurants",
        "Premium consumer tier with travel tip guides and offline maps",
        "White-label tip insights for menu delivery platforms"
      ]
    },
    "market_opportunity": {
      "primary_customers": [
        "diners who want to tip appropriately",
        "frequent travelers",
        "restaurants and hospitality operators",
        "payment and restaurant technology providers"
      ],
      "market_context": "Dining out is a large consumer spending category, and tipping is a common part of the payment experience in many markets. A lightweight, trust-based tool can become a default pre-check behavior.",
      "initial_focus": "Start in one metro area with a high volume of mid-price restaurants and strong tip culture.",
      "scale_strategy": [
        "launch in three major cities",
        "partner with local food blogs and payment apps",
        "integrate with restaurant point-of-sale and payment tools",
        "expand to coffee shops, bars, and delivery where appropriate"
      ]
    },
    "business_model": {
      "revenue_streams": [
        "B2B subscriptions for restaurants and restaurant groups.",
        "API licensing for payment processors, POS vendors, and menu apps.",
        "Premium consumer subscription for travelers and frequent diners.",
        "Sponsored restaurant tip guides and local dining partnerships.",
        "Data insights sold in aggregate and anonymized form."
      ],
      "pricing_examples": {
        "consumer_free": "Basic restaurant tip profiles and calculator.",
        "consumer_premium": "$4 per month or $30 per year for travel guides, historical trends, and offline access.",
        "restaurant_pro": "$49 per month per location for dashboard and team training insights.",
        "api_access": "Tiered monthly pricing based on number of requests and data freshness."
      }
    },
    "go_to_market": {
      "phase_1": {
        "name": "Pilot",
        "duration": "0 to 6 months",
        "actions": [
          "Launch in one city",
          "Onboard 500 restaurants",
