        "name": "Expansion",
        "duration": "6 to 18 months",
        "actions": [
          "Launch in three additional cities",
          "Partner with two payment or POS providers",
          "Introduce Restaurant Pro subscriptions",
          "Publish local tip trend reports to generate press"
        ],
        "success_metrics": [
          "200,000 monthly active users",
          "10,000 restaurant locations with active profiles",
          "$250,000 annual recurring revenue"
        ]
      },
      "phase_3": {
        "name": "Platform",
        "duration": "18 to 36 months",
        "actions": [
          "Launch API platform",
          "Expand to adjacent categories such as bars, coffee, and delivery",
          "Introduce premium consumer features",
          "Scale into international tip markets"
        ],
        "success_metrics": [
          "1,000,000 monthly active users",
          "$2,000,000 annual recurring revenue",
          "API used by 20 enterprise partners"
        ]
      }
    },
    "competitive_advantages": [
      "Simple, high-frequency use case tied directly to a payment moment.",
      "Network effect: more submissions make recommendations more accurate for every user.",
      "Data flywheel: restaurant dashboards encourage owners to promote Tipperary, increasing consumer adoption.",
      "Privacy-first design that avoids requiring payment account access.",
      "Lightweight product that can be embedded into existing payment and restaurant workflows."
    ],
    "risks_and_mitigations": [
      {
        "risk": "Insufficient data for new or small restaurants.",
        "mitigation": "Show confidence ranges, use nearby benchmark estimates, and encourage submissions with simple prompts."
      },
      {
        "risk": "Tip behavior may change over time due to inflation or social pressure.",
        "mitigation": "Use rolling time windows and trend indicators instead of static averages."
      },
      {
        "risk": "Restaurants may worry that tip data could penalize them.",
        "mitigation": "Focus on anonymous, normalized insights and position the product as a customer-experience tool rather than a ranking tool."
      },
      {
        "risk": "Users may not want another app for a small decision.",
        "mitigation": "Integrate with payment apps, QR codes, and restaurant menus to make the tip suggestion accessible at the moment of payment."
      }
    ],
    "financial_highlights": {
      "year_1": "Build data coverage in one city and validate consumer usage.",
      "year_2": "Begin monetizing restaurants and API partners.",
      "year_3": "Reach profitability through B2B subscriptions, API licensing, and premium consumer revenue.",
      "unit_economics_focus": "Low consumer acquisition cost through QR codes and word of mouth, higher B2B lifetime value, and network effects that reduce marginal cost of data quality."
    },
    "funding_ask": {
      "amount": "$1,500,000 seed round",
      "use_of_funds": {
        "product_and_engine": "45 percent",
        "market_data_and_growth": "35 percent",
        "restaurant_sales_and_operations": "15 percent",
        "legal_privacy_and_admin": "5 percent"
      },
      "twelve_month_goals": [
        "Reach 500,000 registered users in three cities.",
        "Build tip data coverage for 25,000 restaurants.",
        "Sign 500 Restaurant Pro subscriptions.",
        "Launch API used by two payment or POS partners."
      ]
    },
    "closing_line": "Tipperary turns tipping anxiety into a simple, data-backed answer: know the average tip size for each restaurant before the check arrives."
  }
}

