  @keyframes spin{to{transform:rotate(360deg)}}

  /* ── masthead ───────────────────────────────── */
  .mast{position:relative;z-index:2;max-width:1120px;margin:0 auto;padding:clamp(1.6rem,4.5vw,3.4rem) clamp(1.2rem,4vw,2.4rem) clamp(1.4rem,3vw,2.2rem)}
  .kicker{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.7rem;letter-spacing:.24em;text-transform:uppercase;color:rgba(242,236,215,.72);border-bottom:1px dashed var(--line-strong);padding-bottom:.9rem}
  .kicker .ref{color:var(--yellow)}
  h1{font-family:"Anton",sans-serif;font-size:clamp(4.6rem,17vw,12.5rem);line-height:.92;letter-spacing:.005em;margin:1.2rem 0 .4rem}
  h1 .dot{color:var(--red)}
  h1 .x{font-size:clamp(1.4rem,4vw,2.6rem);color:var(--yellow);vertical-align:super;letter-spacing:.04em}
  .mast-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:clamp(1.6rem,4vw,3.2rem);align-items:end;margin-top:clamp(1.4rem,3vw,2.4rem)}
  .lede{font-family:"Fraunces",serif;font-style:italic;font-weight:400;font-size:clamp(1.05rem,2vw,1.28rem);line-height:1.65;color:rgba(242,236,215,.9);max-width:46ch}
  .lede em{color:var(--yellow);font-style:italic}
  .lede strong{font-weight:600;color:var(--yellow);font-style:normal}
  .mast-side{display:flex;flex-direction:column;align-items:flex-end;gap:1.3rem}
  .stamp{border:2px solid var(--red);outline:2px solid var(--red);outline-offset:4px;color:var(--red);padding:.9rem 1.3rem;text-align:center;font-weight:700;font-size:.74rem;letter-spacing:.14em;line-height:1.55;text-transform:uppercase;transform:rotate(-6deg);background:rgba(224,66,31,.06)}
  .rhythm{border:1px dashed var(--line-strong);padding:.9rem 1.1rem;min-width:250px}
  .rh-label{display:block;font-size:.62rem;letter-spacing:.24em;text-transform:uppercase;color:rgba(242,236,215,.65);margin-bottom:.6rem}
  .rh-row{display:flex;align-items:center;gap:.35rem;margin:.32rem 0;font-size:.68rem;letter-spacing:.08em;color:rgba(242,236,215,.8)}
  .rh-row b{color:var(--yellow);font-size:.72rem;width:1.1em}
  .dum{background:var(--red);color:var(--paper);padding:2px 8px;border-radius:999px;font-size:.64rem;letter-spacing:.1em}
  .sep{color:var(--red);margin:0 .45rem}

  /* ── ticker ─────────────────────────────────── */
  .ticker{position:relative;z-index:2;overflow:hidden;border-block:1px solid var(--line);background:rgba(0,0,0,.22);padding:.6rem 0}
  .ticker-track{display:flex;width:max-content;animation:tick 60s linear infinite}
  .ticker:hover .ticker-track{animation-play-state:paused}
  .tk-half{display:flex;align-items:center;gap:1.6rem;padding-right:1.6rem;font-size:.74rem;letter-spacing:.16em;text-transform:uppercase;color:rgba(242,236,215,.82);white-space:nowrap}
  .tk-half b{color:var(--red);font-weight:400}
  @keyframes tick{to{transform:translateX(-50%)}}

  /* ── the ledger ─────────────────────────────── */
  .ledger{position:relative;z-index:2;max-width:1080px;margin:clamp(2.4rem,6vw,4.5rem) auto;padding:0 clamp(1.2rem,4vw,2.4rem)}
  .bill{display:grid;grid-template-columns:150px minmax(0,1fr);gap:0 clamp(1.2rem,3vw,2.2rem);margin-bottom:clamp(2.6rem,6vw,4.2rem)}
  .bill:last-child{margin-bottom:0}
  .bill:nth-child(even){grid-template-columns:minmax(0,1fr) 150px}
  .bill:nth-child(even) .bill-rail{order:2;align-items:flex-end;text-align:right}
  .bill-rail{display:flex;flex-direction:column;gap:.7rem;padding-top:1.3rem}
  .bill-num{font-family:"Anton",sans-serif;font-size:clamp(2.6rem,5vw,3.6rem);line-height:1;color:var(--red);transition:transform .3s cubic-bezier(.34,1.56,.64,1),opacity .4s}
  .bill.in:hover .bill-num{transform:rotate(-5deg) scale(1.07)}
  .bill-meter{font-size:.6rem;letter-spacing:.22em;color:rgba(242,236,215,.6);border:1px dashed var(--line-strong);padding:4px 9px}
  .bill-body{position:relative;background:var(--paper);color:var(--ink);border:2px solid var(--ink);box-shadow:8px 8px 0 rgba(0,0,0,.38);padding:1.5rem 1.7rem 1.5rem;transition:transform .25s ease,box-shadow .25s ease;overflow:hidden}
  .bill-body::after{content:"";position:absolute;top:0;right:0;width:170px;height:170px;pointer-events:none;
    background:repeating-radial-gradient(circle at 100% 0%, rgba(16,31,23,.10) 0 1px, transparent 1px 9px);
    -webkit-mask-image:radial-gradient(circle at 100% 0%, #000 30%, transparent 70%);
    mask-image:radial-gradient(circle at 100% 0%, #000 30%, transparent 70%)}
  .bill:hover .bill-body{transform:translate(-3px,-3px);box-shadow:12px 12px 0 rgba(0,0,0,.45)}
  .bill-title{font-family:"Space Grotesk",sans-serif;font-weight:700;font-size:.82rem;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-soft);border-bottom:1px dashed rgba(16,31,23,.35);padding-bottom:.7rem;margin-bottom:1rem;display:inline-block}
  .bill-title:hover{color:var(--red)}
  .ln{font-family:"Fraunces",serif;font-style:italic;font-weight:500;font-size:clamp(1.15rem,2.4vw,1.42rem);line-height:1.6;color:var(--ink);position:relative;padding:0 .18em;margin:0 -.18em}
  .ln::before{content:"";position:absolute;inset:2px 5px;transform:scaleX(0);transform-origin:left center;background:rgba(255,216,74,.5);transition:transform .28s ease;z-index:-1}
  .ln:hover::before{transform:scaleX(1)}
  .ln.b{font-size:.88em;color:var(--ink-soft)}
  .bill-tag{display:inline-block;margin-top:1.1rem;font-size:.6rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--paper);background:var(--red);padding:5px 11px;transform:rotate(-1.5deg)}
  .bill-tag.g{background:#1E4D3B}

  /* line-by-line reveal (JS only) */
  html.js .bill-body .ln{opacity:0;transform:translateY(14px)}
  html.js .bill.in .bill-body .ln{opacity:1;transform:none;transition:opacity .55s ease,transform .55s cubic-bezier(.3,1.5,.55,1)}
  html.js .bill.in .bill-body p.ln:nth-of-type(1){transition-delay:.06s}
  html.js .bill.in .bill-body p.ln:nth-of-type(2){transition-delay:.14s}
  html.js .bill.in .bill-body p.ln:nth-of-type(3){transition-delay:.22s}
  html.js .bill.in .bill-body p.ln:nth-of-type(4){transition-delay:.30s}
  html.js .bill.in .bill-body p.ln:nth-of-type(5){transition-delay:.38s}
  html.js .bill-num{opacity:0;transform:translateY(-10px)}
  html.js .bill.in .bill-num{opacity:1;transform:none;transition:opacity .4s ease,transform .45s cubic-bezier(.3,1.6,.5,1) .1s}

  /* ── colophon & footer ──────────────────────── */
  .colophon{position:relative;z-index:2;max-width:1080px;margin:clamp(2rem,5vw,3.5rem) auto;padding:0 clamp(1.2rem,4vw,2.4rem)}
  .colo-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(260px,.9fr);gap:2.4rem;border-top:2px solid var(--line-strong);padding-top:2rem}
  .colo-h{font-family:"Anton",sans-serif;font-size:clamp(1.5rem,3vw,2rem);letter-spacing:.03em;margin-bottom:.9rem}
  .colo-p{font-family:"Fraunces",serif;font-style:italic;font-size:1rem;line-height:1.7;color:rgba(242,236,215,.85);max-width:48ch}
  .idx-label{display:block;font-size:.62rem;letter-spacing:.24em;text-transform:uppercase;color:rgba(242,236,215,.6);margin-bottom:.9rem}
  .idx-chip{display:inline-block;margin:0 .5rem .6rem 0;font-size:.7rem;letter-spacing:.14em;color:var(--paper);border:1px solid var(--line-strong);padding:5px 12px}
  .idx-chip.hot{background:var(--yellow);color:var(--ink);border-color:var(--yellow);font-weight:700}
  footer{position:relative;z-index:2;text-align:center;padding:2.2rem 1rem 6rem;font-size:.66rem;letter-spacing:.2em;text-transform:uppercase;color:rgba(242,236,215,.45)}

  /* ── fixed UI: meter + dealer ───────────────── */
  .meter{position:fixed;left:1rem;bottom:1rem;z-index:60;display:flex;align-items:center;gap:.6rem;background:var(--paper);color:var(--ink);border:2px solid var(--ink);box-shadow:5px 5px 0 rgba(0,0,0,.45);padding:.55rem .85rem;font-size:.66rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase}
  .meter .ball{width:10px;height:10px;border-radius:50%;background:var(--red);animation:hop .9s infinite}
  .meter b{font-size:.85rem}
  body.paid .meter .ball{animation:none}
  @keyframes hop{0%,100%{transform:translateY(0) scale(1.2,.75)}35%{transform:translateY(-9px) scale(.92,1.1)}70%{transform:translateY(0) scale(1.2,.75)}}
  .deal{position:fixed;right:1rem;bottom:1rem;z-index:60;background:var(--red);color:var(--paper);border:2px solid var(--ink);box-shadow:5px 5px 0 rgba(0,0,0,.45);padding:.65rem 1rem;font-family:"Space Grotesk",sans-serif;font-size:.7rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;transition:transform .18s ease,box-shadow .18s ease}
  .deal:hover{transform:translate(-2px,-2px);box-shadow:7px 7px 0 rgba(0,0,0,.5)}
  .deal:active{transform:translate(2px,2px);box-shadow:0 0 0 rgba(0,0,0,.5)}

  /* ── modal ──────────────────────────────────── */
  .modal{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:1rem;background:rgba(7,18,13,.8);opacity:0;pointer-events:none;transition:opacity .25s ease}
  .modal.open{opacity:1;pointer-events:auto}
  .modal-card{position:relative;background:var(--paper);color:var(--ink);border:2px solid var(--ink);box-shadow:12px 12px 0 rgba(0,0,0,.5);max-width:560px;width:100%;padding:1.9rem 2rem 1.7rem;transform:translateY(14px) scale(.97);transition:transform .28s cubic-bezier(.3,1.4,.5,1)}
  .modal.open .modal-card{transform:none}
  .deal-stamp{position:absolute;top:1rem;right:1.4rem;font-family:"Anton",sans-serif;font-size:1.05rem;letter-spacing:.08em;color:var(--red);border:3px solid var(--red);padding:.25rem .75rem;transform:rotate(8deg)}
  .deal-stamp.pop{animation:stampin .45s cubic-bezier(.2,1.4,.4,1) both}
  @keyframes stampin{0%{transform:scale(2.4) rotate(18deg);opacity:0}60%{transform:scale(.94) rotate(8deg);opacity:1}100%{transform:scale(1) rotate(8deg)}}
  .modal-card h3{font-family:"Space Grotesk",sans-serif;font-weight:700;font-size:.85rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-soft);margin-bottom:1.1rem;padding-right:5.5rem}
  .modal-verse .ln{font-size:1.28rem}
  .modal-actions{display:flex;gap:.8rem;margin-top:1.5rem;flex-wrap:wrap}
  .btn{font-family:"Space Grotesk",sans-serif;font-size:.7rem;font-weight:700;letter-spacing:.15em;text-transform:uppercase;padding:.65rem 1.1rem;border:2px solid var(--ink);background:transparent;color:var(--ink);cursor:pointer;box-shadow:4px 4px 0 var(--ink);transition:transform .15s ease,box-shadow .15s ease}
  .btn:hover{transform:translate(-2px,-2px);box-shadow:6px 6px 0 var(--ink)}
  .btn:active{transform:translate(2px,2px);box-shadow:0 0 0 var(--ink)}
  .btn.red{background:var(--red);color:var(--paper)}

  /* ── paid overlay ───────────────────────────── */
  .paid{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;background:rgba(7,18,13,.6);cursor:pointer}
  .paid.show{display:flex}
  .paid-box{border:5px double var(--red);color:var(--red);padding:1.6rem 2.6rem;text-align:center;transform:rotate(-7deg);background:rgba(12,43,33,.85);animation:stampin .5s cubic-bezier(.2,1.4,.4,1) both}
  .paid-box span{display:block;font-family:"Anton",sans-serif;font-size:clamp(2.2rem,8vw,5rem);letter-spacing:.04em}
  .paid-box small{display:block;margin-top:.7rem;font-size:.66rem;letter-spacing:.2em;text-transform:uppercase;color:rgba(242,236,215,.75)}

  /* ── responsive ─────────────────────────────── */
  @media (max-width:900px){.rosette{display:none}}
  @media (max-width:820px){
    .mast-grid,.colo-grid{grid-template-columns:1fr}
    .mast-side{align-items:flex-start}
  }
  @media (max-width:720px){
    .bill,.bill:nth-child(even){grid-template-columns:1fr}
    .bill:nth-child(even) .bill-rail{order:0;align-items:flex-start;text-align:left}
    .bill-rail{flex-direction:row;align-items:center;gap:1rem;padding:0 0 .8rem}
    .bill-num{font-size:2.2rem}
  }
  @media (max-width:560px){
    .meter .word{display:none}
    .meter{padding:.5rem .7rem}
    .deal{bottom:1rem;right:1rem;font-size:.62rem;padding:.6rem .8rem}
    .meter{bottom:4.4rem;left:1rem}
  }

  /* ── reduced motion ─────────────────────────── */
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none!important;transition:none!important}
    .ticker-track{transform:none}
    html.js .bill-body .ln,html.js .bill-num{opacity:1!important;transform:none!important}
  }
</style>
</head>
<body>

<div class="paybar" aria-hidden="true"><i id="payfill"></i></div>

<svg class="rosette r1" viewBox="0 0 400 400" aria-hidden="true"><g fill="none" stroke="#F2ECD7" stroke-width="1">
