  color:var(--ink);
  font-family:var(--verse);
  font-size:17px;
  overflow-x:hidden;
}
::selection{background:var(--gold);color:var(--ink)}
.grain{
  position:fixed;inset:0;z-index:80;pointer-events:none;opacity:.055;mix-blend-mode:multiply;
  background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="140" height="140"><filter id="n"><feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2"/><feColorMatrix type="saturate" values="0"/></filter><rect width="140" height="140" filter="url(%23n)" opacity="0.6"/></svg>');
}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.mono{font-family:var(--mono)}
.wrap{max-width:1240px;margin:0 auto;padding:0 40px}

/* ============ MASTHEAD ============ */
