  transform:rotate(-1.6deg);position:relative;
}
.stamp:nth-child(2){transform:rotate(1.2deg);border-color:var(--rust);color:var(--rust)}
.stamp:nth-child(3){transform:rotate(-.8deg);border-color:var(--gold-deep);color:var(--gold-deep)}
.hatfig{border:1.5px solid var(--ink);background:var(--paper-hi);padding:18px 16px 14px}
.hatfig svg{width:100%;height:auto;display:block}
.hatfig .hl{stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 1.1s ease}
.mast.go .hatfig .hl{stroke-dashoffset:0}
.hatfig .hl:nth-of-type(2){transition-delay:.15s}
.hatfig .hl:nth-of-type(3){transition-delay:.3s}
.hatfig .hl:nth-of-type(4){transition-delay:.45s}
.hatfig .hl:nth-of-type(5){transition-delay:.6s}
.hat-note{
  font-family:var(--mono);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;
  margin-top:12px;padding-top:10px;border-top:1px dotted var(--ink-line);
  display:flex;justify-content:space-between;gap:10px;color:var(--ink-soft)
}

/* ============ TICKER ============ */
.ticker{background:var(--green);color:var(--paper);overflow:hidden;border-block:1.5px solid var(--ink)}
.tk{display:flex;width:max-content;animation:tk 70s linear infinite}
.tk:hover{animation-play-state:paused}
.tkg{display:flex;align-items:center;font-family:var(--mono);font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;padding:11px 0;white-space:nowrap}
.tkg b{font-weight:500;margin:0 22px;color:var(--gold)}
@keyframes tk{to{transform:translateX(-50%)}}

/* ============ LAYOUT / RAIL ============ */
.layout{
  display:grid;grid-template-columns:252px minmax(0,1fr);gap:58px;
  max-width:1240px;margin:0 auto;padding:52px 40px 90px;
}
.rail{
  position:sticky;top:26px;align-self:start;
  border:1.5px solid var(--ink);background:var(--paper-2);
  padding:18px 18px 16px;box-shadow:5px 5px 0 rgba(34,28,18,.14);
}
.rail-logo{display:flex;align-items:center;gap:10px;padding-bottom:14px;border-bottom:1px dotted var(--ink-line)}
.rail-logo svg{flex:none}
.rail-logo span{font-family:var(--mono);font-size:9px;letter-spacing:.2em;text-transform:uppercase;line-height:1.7;color:var(--ink-soft)}
.rail-sec{padding:16px 0;border-bottom:1px dotted var(--ink-line)}
.lab{font-family:var(--mono);font-size:9px;letter-spacing:.24em;text-transform:uppercase;color:var(--rust)}
.rail-count{font-family:var(--display);font-weight:700;font-size:2.5rem;line-height:1.1;margin-top:4px}
.rail-count i{font-style:normal;font-size:1rem;font-weight:400;color:var(--ink-soft)}
.rail-bar{margin-top:10px;height:5px;border:1px solid var(--ink);background:var(--paper-hi);position:relative}
.rail-bar .fill{position:absolute;inset:0;width:0%;background:repeating-linear-gradient(-45deg,var(--gold) 0 4px,var(--rust) 4px 8px);transition:width .5s cubic-bezier(.2,.7,.3,1)}
.dots{padding:14px 0 4px}
.dotgroup{display:flex;align-items:center;gap:8px;margin-top:10px}
.dotgroup:first-child{margin-top:0}
.dotgroup .gl{font-family:var(--mono);font-size:8.5px;color:var(--ink-soft);width:14px}
.dot{
  width:14px;height:14px;border:1px solid var(--ink);background:transparent;
  cursor:pointer;padding:0;transition:background .3s,transform .2s;
}
.dot:hover{transform:scale(1.25);background:var(--gold)}
.dot.passed{background:var(--gold)}
.dot.current{background:var(--rust);animation:pulse 1.6s ease-in-out infinite}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(160,75,38,.5)}50%{box-shadow:0 0 0 5px rgba(160,75,38,0)}}
.rail-note{font-family:var(--mono);font-size:9.5px;font-style:italic;color:var(--ink-soft);margin-top:14px;line-height:1.7}

/* ============ CHAPTERS ============ */
.chap{margin-top:82px}
.chap:first-child{margin-top:0}
.chap-head{
  display:flex;align-items:flex-end;justify-content:space-between;gap:36px;
  border-bottom:3px solid var(--ink);padding-bottom:20px;
}
.chap-title{
  font-family:var(--display);font-weight:700;font-size:clamp(2rem,4.4vw,3.3rem);
  line-height:1.05;letter-spacing:-.01em;margin-top:10px;overflow:hidden;
}
.chap-title .cw{display:inline-block;transform:translateY(115%);transition:transform .9s cubic-bezier(.2,.75,.2,1)}
.chap.in .chap-title .cw{transform:translateY(0)}
.chap-title em{font-style:italic;color:var(--green)}
.fig{flex:none;width:236px}
.fig .frame{border:1.5px solid var(--ink);padding:7px;background:var(--paper-hi);box-shadow:4px 4px 0 rgba(34,28,18,.12)}
.fig .kb{overflow:hidden;aspect-ratio:16/10}
.fig img{width:100%;height:100%;object-fit:cover;filter:sepia(.4) contrast(1.06) saturate(.75) brightness(.98);display:block;animation:kb 22s ease-in-out infinite alternate}
@keyframes kb{from{transform:scale(1) translate(0,0)}to{transform:scale(1.1) translate(-2.5%,-2%)}}
.fig figcaption{font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-soft);margin-top:9px;text-align:right}

/* ============ PLATES ============ */
.plate{
  position:relative;display:grid;grid-template-columns:128px minmax(0,1fr);gap:30px;
  padding:38px 0 34px;border-bottom:1px dotted var(--ink-line);
}
.plate-num{
  font-family:var(--display);font-weight:700;font-size:4.4rem;line-height:.95;
  color:rgba(34,28,18,.22);letter-spacing:-.02em;
}
@supports (-webkit-text-stroke:1px black){
  .plate-num{color:transparent;-webkit-text-stroke:1.6px var(--ink)}
}
.plate-num small{display:block;font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--ink-soft);-webkit-text-stroke:0;margin-top:8px}
.plate:hover .plate-num{color:var(--gold)}
@supports (-webkit-text-stroke:1px black){.plate:hover .plate-num{color:var(--gold);-webkit-text-stroke:1.6px var(--gold)}}
.plate.pop .plate-num{animation:numpop .45s ease}
@keyframes numpop{40%{transform:scale(1.08) rotate(-2deg)}100%{transform:scale(1)}}
.plate-title{
  font-family:var(--display);font-weight:600;font-style:italic;font-size:1.6rem;
  margin-bottom:16px;opacity:0;transform:translateY(10px);transition:opacity .6s,transform .6s;
}
.plate.in .plate-title{opacity:1;transform:none}
.plate-title::before{content:"¶ ";color:var(--rust);font-style:normal}
.hat{max-width:640px}
.ln{
  position:relative;text-align:center;font-size:1.34rem;line-height:1.62;
  padding:0 2.6ch;font-weight:500;
  opacity:0;transform:translateY(14px);
  transition:opacity .65s ease,transform .65s cubic-bezier(.2,.7,.3,1);
}
.plate.in .ln{opacity:1;transform:none}
.plate.in .ln:nth-child(1){transition-delay:.05s}
.plate.in .ln:nth-child(2){transition-delay:.16s}
.plate.in .ln:nth-child(3){transition-delay:.27s}
.plate.in .ln:nth-child(4){transition-delay:.38s}
.plate.in .ln:nth-child(5){transition-delay:.49s}
.ln.l2{font-size:1.16rem;margin:0 3%}
.ln.l3,.ln.l4{font-size:1.02rem;margin:0 11%;font-style:italic;color:var(--green-2)}
.sc{
  position:absolute;left:0;top:50%;transform:translateY(-50%);
  font-family:var(--mono);font-style:normal;font-size:9px;letter-spacing:.08em;
}
.scA{color:var(--gold-deep)}
.scB{color:var(--rust)}
.drop{
  font-family:var(--display);font-weight:900;font-size:2.05em;line-height:0;
  color:var(--rust);margin-right:.05em;display:inline-block;transform:translateY(.12em);
}
.name{font-family:var(--display);font-style:italic;font-weight:700;color:var(--green);font-size:1.04em}
.name.j{color:var(--gold-deep)}
.plate-foot{
  display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;
  margin-top:24px;opacity:0;transition:opacity .6s .55s;
}
.plate.in .plate-foot{opacity:1}
.cast{font-family:var(--mono);font-size:10.5px;letter-spacing:.06em;color:var(--ink-soft)}
.clap{
  position:relative;font-family:var(--mono);font-size:11px;letter-spacing:.16em;
  border:1.5px solid var(--ink);background:transparent;color:var(--ink);
  padding:8px 16px;cursor:pointer;transition:background .18s,color .18s,transform .1s;
}
.clap b{font-weight:600;color:var(--rust);margin-left:8px}
.clap:hover{background:var(--ink);color:var(--paper)}
.clap:hover b{color:var(--gold)}
.clap:active{transform:scale(.93)}
.stamp-pop{
  position:absolute;left:50%;top:-34px;transform:translate(-50%,0);
  font-family:var(--display);font-weight:900;font-size:1.05rem;color:var(--rust);
  pointer-events:none;animation:stamp .8s ease-out forwards;white-space:nowrap;
}
@keyframes stamp{
  0%{opacity:0;transform:translate(-50%,8px) rotate(-14deg) scale(1.5)}
  25%{opacity:1;transform:translate(-50%,-6px) rotate(-9deg) scale(1)}
  100%{opacity:0;transform:translate(-50%,-30px) rotate(-4deg) scale(.9)}
}

/* ============ FOOTER ============ */
.foot{background:var(--green-2);color:var(--paper);margin-top:96px;border-top:4px solid var(--ink)}
.foot-in{max-width:1240px;margin:0 auto;padding:64px 40px 46px;display:grid;grid-template-columns:auto 1fr auto;gap:52px;align-items:start}
.fin{font-family:var(--display);font-weight:900;font-size:clamp(4rem,9vw,7.5rem);line-height:.9}
.fin i{font-style:normal;color:var(--gold)}
.fin small{display:block;font-family:var(--mono);font-weight:400;font-size:10px;letter-spacing:.24em;text-transform:uppercase;margin-top:14px;color:rgba(243,233,210,.66)}
.colophon{font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;line-height:2.1;color:rgba(243,233,210,.8);text-transform:lowercase;max-width:56ch}
.colophon b{color:var(--gold);font-weight:500;text-transform:uppercase;letter-spacing:.2em}
.colophon .rule{display:block;margin:14px 0;border-top:1px dotted rgba(243,233,210,.4);position:relative;top:6px}
.foot-appl{text-align:right}
.foot-appl .big{font-family:var(--display);font-weight:700;font-size:3.4rem;line-height:1;color:var(--gold)}
.foot-appl .cap{font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;text-transform:uppercase;margin-top:8px;color:rgba(243,233,210,.66)}
.foot-base{border-top:1px solid rgba(243,233,210,.25);max-width:1240px;margin:0 auto;padding:16px 40px 26px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:rgba(243,233,210,.55)}

/* ============ RESPONSIVE ============ */
@media (max-width:1023px){
  .wrap{padding:0 22px}
  .layout{grid-template-columns:1fr;gap:30px;padding:36px 22px 70px}
  .rail{
    top:0;z-index:50;display:flex;align-items:center;gap:18px;
    padding:10px 16px;box-shadow:0 4px 0 rgba(34,28,18,.12);
  }
  .rail-logo span{display:none}
  .rail-sec{padding:0;border:none}
  .rail-count{font-size:1.5rem}
  .rail-bar{flex:1;margin:0;min-width:60px}
  .dots,.rail-note{display:none}
  .rail-appl .lab{display:none}
  .mast-grid{grid-template-columns:1fr}
  .chap-head{flex-direction:column;align-items:stretch;gap:22px}
  .fig{width:100%;max-width:340px}
  .plate{grid-template-columns:1fr;gap:8px;padding:30px 0 28px}
  .plate-num{font-size:3rem;display:flex;align-items:baseline;gap:14px}
  .plate-num small{margin-top:0}
  .foot-in{grid-template-columns:1fr;gap:34px}
  .foot-appl{text-align:left}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
  .word,.cw,.ln,.plate-title,.plate-foot{opacity:1!important;transform:none!important}
  .tk{animation:none}
  .hatfig .hl{stroke-dashoffset:0}
  .fig img{animation:none}
}
</style>
</head>
<body>
<div class="grain" aria-hidden="true"></div>

<!-- ================= MASTHEAD ================= -->
<header class="wrap mast" id="mast">
  <div class="topline">
    <span>Published weekly in Limerick, Co. Limerick</span>
    <span>Anapestic edition · o o ÚM</span>
    <span>No. 25 — Price: one limerick</span>
  </div>

  <p class="kick" id="mastKick" data-text="Five chapters · Twenty-five stanzas · One name">Five chapters · Twenty-five stanzas · One name</p>

  <h1 class="bigline">
    <span class="mask"><span class="word w-the">The</span></span>
    <span class="mask"><span class="word w-bill">BILL</span></span>
    <span class="mask"><span class="word w-almanack">ALMANACK</span></span>
  </h1>

  <div class="mast-grid">
    <div>
      <p class="mast-sub">Being twenty-five limericks concerning persons <em>named Bill</em> — brewer to buccaneer, ghost to grandmaster — set in the shape of their proper hat, and filed with their rhyme schemes for the record. One <em>Jürgen</em> is cited; he is noted, but emphatically not a Bill.</p>
      <div class="stamps" aria-label="index of names">
        <span class="stamp">filed: bill</span>
        <span class="stamp">filed: economist</span>
        <span class="stamp">filed: jurgen</span>
      </div>
    </div>
    <figure class="hatfig" aria-label="the limerick hat: line lengths seven, four, five, five, seven">
      <svg viewBox="0 0 260 178" role="img">
        <g stroke-width="1" font-family="IBM Plex Mono, monospace" font-size="9" fill="rgba(34,28,18,.6)">
          <text x="2" y="22">A·7</text><text x="2" y="56">A·4</text><text x="2" y="90">B·5</text><text x="2" y="120">B·5</text><text x="2" y="154">A·7</text>
        </g>
        <line class="hl" pathLength="1" x1="34" y1="18"  x2="252" y2="18"  stroke="#221c12" stroke-width="6" stroke-linecap="round"/>
        <line class="hl" pathLength="1" x1="108" y1="52" x2="178" y2="52" stroke="#221c12" stroke-width="6" stroke-linecap="round"/>
        <line class="hl" pathLength="1" x1="82"  y1="86" x2="204" y2="86" stroke="#a04b26" stroke-width="5" stroke-linecap="round"/>
        <line class="hl" pathLength="1" x1="82"  y1="116" x2="204" y2="116" stroke="#a04b26" stroke-width="5" stroke-linecap="round"/>
        <line class="hl" pathLength="1" x1="34" y1="150" x2="252" y2="150" stroke="#221c12" stroke-width="6" stroke-linecap="round"/>
        <text x="143" y="176" font-family="IBM Plex Mono, monospace" font-size="9" fill="rgba(34,28,18,.6)">a limerick is a hat</text>
      </svg>
      <figcaption class="hat-note"><span>aa / bba</span><span>≈ 7·4·5·5·7 syllables</span></figcaption>
    </figure>
  </div>
</header>

<!-- ================= TICKER ================= -->
<div class="ticker" aria-hidden="true">
  <div class="tk" id="tk"></div>
</div>

<!-- ================= LAYOUT ================= -->
<div class="layout">

  <aside class="rail" aria-label="progress">
    <div class="rail-logo">
      <svg width="34" height="26" viewBox="0 0 34 26" aria-hidden="true">
        <line x1="3" y1="4" x2="31" y2="4" stroke="#221c12" stroke-width="3.4" stroke-linecap="round"/>
        <line x1="12" y1="11" x2="22" y2="11" stroke="#a04b26" stroke-width="3" stroke-linecap="round"/>
        <line x1="8" y1="18" x2="26" y2="18" stroke="#a04b26" stroke-width="3" stroke-linecap="round"/>
        <line x1="3" y1="25" x2="31" y2="25" stroke="#221c12" stroke-width="3.4" stroke-linecap="round" transform="translate(0,-2.5)"/>
      </svg>
      <span>The Bill<br>Almanack</span>
    </div>
    <div class="rail-sec">
      <span class="lab">Stanza</span>
      <div class="rail-count"><span id="cnt">00</span><i> / 25</i></div>
      <div class="rail-bar"><div class="fill" id="bar"></div></div>
    </div>
    <nav class="dots" id="dots"></nav>
    <div class="rail-sec rail-appl">
      <span class="lab">Applause</span>
      <div class="rail-count" id="applRail">0</div>
    </div>
    <p class="rail-note">Clap often — bills<br>appreciate it.</p>
  </aside>

  <main id="main">

    <!-- ============ PART I ============ -->
    <section class="chap" data-chap="1">
      <header class="chap-head">
        <div>
          <p class="kick" data-text="Part I · of V">Part I · of V</p>
          <h2 class="chap-title"><span class="cw"><em>Bills</em> of Trade</span></h2>
        </div>
        <figure class="fig">
          <div class="frame"><div class="kb"><img src="https://picsum.photos/seed/bill-brewery-almanac/640/400" alt="An engraving-style illustration of a bustling trade street" loading="lazy"></div></div>
          <figcaption>fig. i — a trade street, at dawn</figcaption>
        </figure>
      </header>

      <article class="plate" id="p1" data-n="1">
        <div class="plate-num">I<small>of 25</small></div>
        <div class="plate-body">
          <h3 class="plate-title"><span class="sr">Stanza 1 — </span>Bill the Brewer</h3>
          <div class="hat">
            <p class="ln l1"><i class="sc scA">A</i><span class="drop">T</span>here once was a Bill in the brewery,</p>
            <p class="ln l2"><i class="sc scA">A</i>Who tapped up the casks for his money;</p>
            <p class="ln l3"><i class="sc scB">B</i>He'd crown each tall pint</p>
            <p class="ln l4"><i class="sc scB">B</i>With a flourish of mint,</p>
            <p class="ln l5"><i class="sc scA">A</i>'Til a hump struck his head in the brewery.</p>
          </div>
          <div class="plate-foot">
            <span class="cast">cast: bill the brewer · one hump · several pints</span>
            <button class="clap" aria-label="applaud stanza 1">CLAP <b>0</b></button>
          </div>
        </div>
      </article>

      <article class="plate" id="p2" data-n="2">
        <div class="plate-num">II<small>of 25</small></div>
        <div class="plate-body">
          <h3 class="plate-title"><span class="sr">Stanza 2 — </span>Bill the Baker</h3>
          <div class="hat">
            <p class="ln l1"><i class="sc scA">A</i><span class="drop">T</span>here once was a Bill at the bakery,</p>
            <p class="ln l2"><i class="sc scA">A</i>Who dusted the whole street in a flurry;</p>
            <p class="ln l3"><i class="sc scB">B</i>His sourdough, they swore,</p>
            <p class="ln l4"><i class="sc scB">B</i>Could come back from the war,</p>
            <p class="ln l5"><i class="sc scA">A</i>And sold out by ten at the bakery.</p>
          </div>
          <div class="plate-foot">
            <span class="cast">cast: bill the baker · one sourdough · one veteran loaf</span>
            <button class="clap" aria-label="applaud stanza 2">CLAP <b>0</b></button>
          </div>
        </div>
      </article>

      <article class="plate" id="p3" data-n="3">
        <div class="plate-num">III<small>of 25</small></div>
        <div class="plate-body">
          <h3 class="plate-title"><span class="sr">Stanza 3 — </span>Bill the Blacksmith</h3>
          <div class="hat">
            <p class="ln l1"><i class="sc scA">A</i><span class="drop">T</span>here once was a Bill at the forge in the town,</p>
            <p class="ln l2"><i class="sc scA">A</i>Whose hammering carried a mile all around;</p>
            <p class="ln l3"><i class="sc scB">B</i>The anvil, they'd swear,</p>
            <p class="ln l4"><i class="sc scB">B</i>Broke into a roar,</p>
            <p class="ln l5"><i class="sc scA">A</i>And rang out the evening from hill to the ground.</p>
          </div>
          <div class="plate-foot">
            <span class="cast">cast: bill the blacksmith · one anvil · one chimney cat</span>
            <button class="clap" aria-label="applaud stanza 3">CLAP <b>0</b></button>
          </div>
        </div>
      </article>

      <article class="plate" id="p4" data-n="4">
        <div class="plate-num">IV<small>of 25</small></div>
        <div class="plate-body">
          <h3 class="plate-title"><span class="sr">Stanza 4 — </span>Bill the Barber</h3>
          <div class="hat">
            <p class="ln l1"><i class="sc scA">A</i><span class="drop">T</span>here once was a Bill with a clipper that clipped,</p>
            <p class="ln l2"><i class="sc scA">A</i>He hummed as he faded, a barbering trip;</p>
            <p class="ln l3"><i class="sc scB">B</i>He'd clip, then he'd shear,</p>
            <p class="ln l4"><i class="sc scB">B</i>The fringe and the ear,</p>
            <p class="ln l5"><i class="sc scA">A</i>And part down the middle without dropping a clip.</p>
          </div>
          <div class="plate-foot">
            <span class="cast">cast: bill the barber · one clipper · one very tidy crown</span>
            <button class="clap" aria-label="applaud stanza 4">CLAP <b>0</b></button>
          </div>
        </div>
      </article>

      <article class="plate" id="p5" data-n="5">
        <div class="plate-num">V<small>of 25</small></div>
        <div class="plate-body">
          <h3 class="plate-title"><span class="sr">Stanza 5 — </span>Bill the Tailor</h3>
          <div class="hat">
            <p class="ln l1"><i class="sc scA">A</i><span class="drop">T</span>here once was a Bill with a bobbin of twine,</p>
            <p class="ln l2"><i class="sc scA">A</i>Who stitched all the coats of the village's line;</p>
            <p class="ln l3"><i class="sc scB">B</i>His stitchings were fine,</p>
            <p class="ln l4"><i class="sc scB">B</i>He could hem up a whale's spine,</p>
