<script>
(function(){
  const RM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const TITLES = [
    "Bill the Brewer","Bill the Baker","Bill the Blacksmith","Bill the Barber","Bill the Tailor",
    "Bill the Lighthouse Keeper","Bill the Angler","Bill the Buccaneer","Bill the Dockhand","Bill the Ferry Bet",
    "Bill the Botanist","Bill the Comet Finder","Bill the Grandmaster","Bill the Chemist","Bill the Economist",
    "Bill the Gardener","A Dog Named Bill","Bill the Grandfather","Bill the Chef","Bill the Lawnmower",
    "Bill from Planet Unseen","Bill the Ghost","Bill the Time-Traveler","Bilbot, Model Bill","Bill the Last"
  ];
  const CHAP_NAMES = ["Trades","Sea","Mind","Home","Absurd"];

  /* ---- wrap the name "Bill" (and friends) in the verse ---- */
  document.querySelectorAll('.ln').forEach(function(ln){
    const html = ln.innerHTML.replace(/(Bilbot|Bill|Jurgen)/g, function(m){
      return m === 'Jurgen' ? '<span class="name j">Jurgen</span>' : '<span class="name">'+m+'</span>';
    });
    ln.innerHTML = html;
  });

  /* ---- masthead line-mask reveal + hat draw ---- */
  window.addEventListener('load', function(){
    document.getElementById('mast').classList.add('go');
  });

  /* ---- ticker (built twice for a seamless loop) ---- */
  const items = TITLES.map(t => t).concat(["Jurgen (noted, not a Bill)","The limerick is a hat"]);
  const group = items.map(t => '<span>'+t+'</span><b>✶</b>').join('');
  document.getElementById('tk').innerHTML =
    '<div class="tkg">'+group+'</div><div class="tkg" aria-hidden="true">'+group+'</div>';

  /* ---- build the 25-dot rail index ---- */
  const dotsWrap = document.getElementById('dots');
  const ROM = ["I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII","XIII","XIV","XV","XVI","XVII","XVIII","XIX","XX","XXI","XXII","XXIII","XXIV","XXV"];
  for(let g=0; g<5; g++){
    const grp = document.createElement('div');
    grp.className = 'dotgroup';
    grp.innerHTML = '<span class="gl">'+['I','II','III','IV','V'][g]+'</span>';
    for(let i=0; i<5; i++){
      const n = g*5 + i + 1;
      const b = document.createElement('button');
      b.className = 'dot';
      b.dataset.n = n;
      b.title = ROM[n-1]+' — '+TITLES[n-1];
      b.setAttribute('aria-label','Go to stanza '+n+': '+TITLES[n-1]);
      b.addEventListener('click', function(){
        document.getElementById('p'+n).scrollIntoView({behavior: RM ? 'auto' : 'smooth', block:'center'});
      });
      grp.appendChild(b);
    }
    dotsWrap.appendChild(grp);
  }
  const allDots = Array.from(dotsWrap.querySelectorAll('.dot'));
  const cnt = document.getElementById('cnt');
  const bar = document.getElementById('bar');

  function setStanza(n){
    cnt.textContent = String(n).padStart(2,'0');
    bar.style.width = (n/25*100)+'%';
    allDots.forEach(function(d){
      const dn = +d.dataset.n;
      d.classList.toggle('passed', dn < n);
      d.classList.toggle('current', dn === n);
    });
  }

  /* ---- scramble-decode kickers ---- */
  const CHARS = 'ABEFLMNORSTUV✶*§&%#';
  function scramble(el){
    if(RM) return;
    const final = el.dataset.text || el.textContent;
    const len = final.length;
    let frame = 0;
    const total = Math.max(14, len);
    const iv = setInterval(function(){
      frame++;
      let out = '';
      for(let i=0; i<len; i++){
        if(final[i] === ' '){ out += ' '; continue; }
        out += (i < (frame/total)*len) ? final[i] : CHARS[Math.floor(Math.random()*CHARS.length)];
      }
      el.textContent = out;
      if(frame >= total){ el.textContent = final; clearInterval(iv); }
    }, 34);
  }

  /* ---- reveals & chapter titles ---- */
  const ioReveal = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(!e.isIntersecting) return;
      e.target.classList.add('in');
      const k = e.target.querySelector ? e.target.querySelector('.kick') : null;
      if(k && !k.dataset.done){ k.dataset.done = '1'; scramble(k); }
      ioReveal.unobserve(e.target);
