(function(){
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ── staggered reveals ── */
  var revEls = document.querySelectorAll('.rev');
  if ('IntersectionObserver' in window && !reduced) {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, {threshold:.1, rootMargin:'0px 0px -6% 0px'});
    revEls.forEach(function(el, i){
      el.style.setProperty('--d', Math.min((i % 4) * 90, 270) + 'ms');
      io.observe(el);
    });
  } else {
    revEls.forEach(function(el){ el.classList.add('in'); });
  }

  /* ── recite: line-by-line carry ── */
  document.querySelectorAll('.recite').forEach(function(btn){
    btn.addEventListener('click', function(){
      var lim = btn.closest('.lim');
      if (lim.classList.contains('reciting')) return;
      var lines = lim.querySelectorAll('.poem .ln');
      var original = btn.textContent;
      lim.classList.add('reciting');
      lines.forEach(function(l){ l.classList.remove('lit'); });
      if (reduced) {
        lines.forEach(function(l){ l.classList.add('lit'); });
        lim.classList.add('stamped');
        setTimeout(function(){
          lines.forEach(function(l){ l.classList.remove('lit'); });
          lim.classList.remove('reciting');
          btn.textContent = original;
        }, 1600);
        return;
      }
      btn.textContent = '· · reciting · ·';
      lines.forEach(function(l, i){
        setTimeout(function(){
          l.classList.add('lit');
          if (i === lines.length - 1) {
            setTimeout(function(){
              lim.classList.add('stamped');
              lines.forEach(function(l2){ l2.classList.remove('lit'); });
              lim.classList.remove('reciting');
              btn.textContent = original;
            }, 750);
          }
        }, 520 * i);
      });
    });
  });

  /* ── ledger count-up ── */
  var counters = document.querySelectorAll('[data-count]');
  if ('IntersectionObserver' in window) {
    var cio = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (!e.isIntersecting) return;
        var el = e.target; cio.unobserve(el);
        var target = parseInt(el.getAttribute('data-count'), 10);
        if (reduced || target === 0) { el.textContent = target; return; }
        var t0 = performance.now(), dur = 1000;
        function step(now){
          var p = Math.min((now - t0) / dur, 1);
          el.textContent = Math.round(target * (1 - Math.pow(1 - p, 3)));
          if (p < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      });
    }, {threshold:.5});
    counters.forEach(function(c){ cio.observe(c); });
  } else {
    counters.forEach(function(c){ c.textContent = c.getAttribute('data-count'); });
  }

  /* ── order form → dispatch stamp ── */
  var form = document.getElementById('orderForm');
  form.addEventListener('submit', function(e){
    e.preventDefault();
    var n = String(100 + Math.floor(Math.random() * 900));
    var qty = form.querySelector('[name="qty"]').value;
    var box = document.getElementById('orderResult');
    box.innerHTML =
      '<span class="stamp-line show">Received · N° ' + n + ' · ' + qty +
      ' · one bill enclosed</span>' +
      '<p>A bill of lading follows by post — by a mail-Bill, naturally. ' +
      'No refunds; the verse is already printed.</p>';
    box.hidden = false;
    form.classList.add('done');
    if (!reduced) { box.scrollIntoView({behavior:'smooth', block:'nearest'}); }
  });
})();
</script>
</body>
</html>
