    color:var(--ink-60);transition:letter-spacing .3s ease,color .2s;
  }
  .lim:hover .place{letter-spacing:.18em;color:var(--ink)}
  .recite{
    margin-left:auto;font-family:var(--mono);font-size:.62rem;letter-spacing:.14em;text-transform:uppercase;
    background:none;border:none;border-bottom:1px dotted var(--teal);color:var(--teal);
    padding:3px 2px;cursor:pointer;transition:color .2s,border-color .2s;
  }
  .recite:hover{color:var(--verm);border-bottom:1px solid var(--verm)}
  .recite:active{transform:translateY(1px)}
  .lim-rule{border-top:1px solid var(--ink-30);position:relative;margin:10px 0 12px}
  .lim-rule::after{content:"";position:absolute;right:0;top:-1px;width:38px;height:3px;background:var(--verm)}
  .poem{font-size:1.07rem;line-height:1.82}
  .poem .ln{display:block;padding:1px 3px;margin:0 -3px}
  .poem .ln.lit{background:rgba(185,138,31,.34);box-decoration-break:clone;-webkit-box-decoration-break:clone;color:var(--verm)}
  .note{
    margin-top:14px;font-family:var(--mono);font-size:.67rem;line-height:1.75;
    color:var(--teal);padding-left:12px;border-left:2px solid var(--teal);
  }
  .note b{display:block;font-weight:700;font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;margin-bottom:3px}
  .stamp{
    position:absolute;top:-8px;right:0;font-family:var(--mono);font-size:.58rem;letter-spacing:.18em;
    text-transform:uppercase;color:var(--verm);border:1.5px solid var(--verm);padding:4px 8px;
    background:var(--paper);transform:rotate(7deg) scale(0);
    transition:transform .4s cubic-bezier(.2,1.5,.4,1);
  }
  .lim.stamped .stamp{transform:rotate(-6deg) scale(1)}

  /* ledger */
  .ledger-rows{max-width:760px}
  .lrow{display:flex;align-items:baseline;gap:14px;padding:16px 0;border-bottom:1px dotted var(--ink-30)}
  .lrow:first-child{border-top:1px dotted var(--ink-30)}
  .lrow .ll{font-family:var(--mono);font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60)}
  .lrow .ld{flex:1;border-bottom:1px dotted var(--ink-30);transform:translateY(-4px)}
  .lrow .lv{font-family:var(--disp);font-weight:700;font-size:clamp(1.7rem,3.4vw,2.5rem);color:var(--verm);line-height:1;font-variant-numeric:tabular-nums}
  .ledger-fine{margin-top:22px;font-family:var(--mono);font-size:.66rem;letter-spacing:.1em;color:var(--ink-60)}

  /* order */
  .order-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(30px,5vw,64px);align-items:start}
  .prices{border:1px solid var(--ink-30);padding:24px 26px}
  .prices-title{font-family:var(--mono);font-size:.66rem;letter-spacing:.28em;text-transform:uppercase;color:var(--verm);margin-bottom:14px}
  .prow{display:flex;align-items:baseline;gap:12px;padding:10px 0;font-size:.95rem;font-style:italic}
  .prow .ld{flex:1;border-bottom:1px dotted var(--ink-30);transform:translateY(-3px)}
  .prow .pval{font-family:var(--mono);font-style:normal;font-size:.74rem;color:var(--ink-60)}
  .prices .fine{margin-top:16px;font-family:var(--mono);font-size:.64rem;line-height:1.8;letter-spacing:.06em;color:var(--ink-60)}
  form .field{margin-bottom:22px}
  .flabel{display:block;font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-60);margin-bottom:8px}
  input[type=text],select{
    width:100%;background:transparent;border:none;border-bottom:1.5px solid var(--ink);
    font-family:var(--serif);font-style:italic;font-size:1.05rem;color:var(--ink);
    padding:9px 2px;transition:border-color .25s;border-radius:0;
  }
  input[type=text]::placeholder{color:var(--ink-30)}
  input[type=text]:focus,select:focus{outline:none;border-color:var(--verm)}
  select{cursor:pointer}
  .f-fine{font-family:var(--mono);font-size:.62rem;line-height:1.8;letter-spacing:.06em;color:var(--ink-60);margin:4px 0 22px}
  .dispatch{
    font-family:var(--mono);font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;
    background:var(--ink);color:var(--paper);border:1px solid var(--ink);
    padding:14px 22px;cursor:pointer;transition:background .25s,border-color .25s,transform .12s;
  }
  .dispatch:hover{background:var(--verm);border-color:var(--verm)}
  .dispatch:active{transform:translateY(2px)}
  #orderForm.done{opacity:.35;pointer-events:none;transition:opacity .5s}
  #orderResult{margin-top:28px}
  .stamp-line{
    display:inline-block;font-family:var(--mono);font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;
    color:var(--verm);border:2px solid var(--verm);outline:1px solid var(--verm);outline-offset:3px;
    padding:13px 18px;background:rgba(166,61,42,.05);transform:rotate(-4deg);
  }
  #orderResult p{margin-top:16px;font-family:var(--mono);font-size:.64rem;line-height:1.9;letter-spacing:.08em;color:var(--ink-60);max-width:44ch}

  /* colophon */
  .colophon{border-top:3px double var(--ink-60);padding:38px 0 54px;text-align:center}
  .colophon .rule-orn{max-width:340px;margin:0 auto 24px}
  .colo-text{font-family:var(--mono);font-size:.68rem;line-height:2;letter-spacing:.1em;color:var(--ink-60);max-width:62ch;margin:0 auto}
  .colo-text em{color:var(--ink);font-style:italic}
  .top{
    display:inline-block;margin-top:20px;font-family:var(--mono);font-size:.66rem;letter-spacing:.24em;
    text-transform:uppercase;color:var(--verm);text-decoration:none;border-bottom:1px dotted var(--verm);padding:4px 2px;
    transition:border-color .2s;
  }
  .top:hover{border-bottom:1px solid var(--verm)}

  .side-note{
    position:fixed;left:20px;top:50%;transform:translateY(-50%);z-index:65;
    writing-mode:vertical-rl;transform:translateY(-50%) rotate(180deg);
    font-family:var(--mono);font-size:.6rem;letter-spacing:.34em;text-transform:uppercase;
    color:var(--ink-60);white-space:nowrap;
  }

  /* ── motion ─────────────────────────── */
  @media (prefers-reduced-motion: no-preference){
    html{scroll-behavior:smooth}
    .rev{opacity:0;transform:translateY(18px);transition:opacity .7s ease var(--d,0ms),transform .7s cubic-bezier(.2,.7,.2,1) var(--d,0ms)}
    .rev.in{opacity:1;transform:none}
    .lm-in{transform:translateY(112%);animation:rise 1s .18s cubic-bezier(.2,.9,.25,1) forwards}
    .lm:nth-child(2) .lm-in{animation-delay:.34s}
    @keyframes rise{to{transform:translateY(0)}}
    .ticker-track{animation:tick 38s linear infinite}
    @keyframes tick{to{transform:translateX(-50%)}}
    .seal .spin{animation:spin 48s linear infinite}
    @keyframes spin{to{transform:rotate(360deg)}}
    .bunting{animation:sway 9s ease-in-out infinite;transform-origin:top center}
    @keyframes sway{0%,100%{transform:rotate(.5deg)}50%{transform:rotate(-.5deg)}}
    .plate .kb img{animation:kb 26s ease-in-out infinite alternate}
    .aside-plate .kb img{animation:kb 22s ease-in-out infinite alternate}
    @keyframes kb{from{transform:scale(1.03)}to{transform:scale(1.15) translate(-2.4%,1.8%)}}
    .stamp-line.show{animation:stampIn .55s cubic-bezier(.18,1.5,.4,1)}
    @keyframes stampIn{0%{transform:rotate(4deg) scale(1.7);opacity:0}100%{transform:rotate(-4deg) scale(1);opacity:1}}
  }
  @media (prefers-reduced-motion: reduce){
    *{animation:none!important;transition:none!important}
  }

  /* responsive */
  @media (max-width:1199px){.side-note{display:none}}
  @media (max-width:980px){
    .mast-top span:nth-child(2){display:none}
    .order-grid{grid-template-columns:1fr}
  }
  @media (max-width:920px){
    .catalogue-cols{columns:1}
    .catalogue-cols::before{display:none}
    .lim::after{left:-8px}
    .fore-grid{grid-template-columns:1fr}
    .aside-plate{max-width:300px}
  }
  @media (max-width:720px){
    .toc{columns:1}
    .mast-main{grid-template-columns:1fr}
    .seal-wrap{width:120px}
    .mast-top{font-size:.58rem}
    .frame{inset:7px}
  }
</style>
</head>
